const resourceApprovalCounts = `-- name: ResourceApprovalCounts :many
SELECT s.resource_id, count(DISTINCT s.id)::integer AS approved_count
FROM resource_assets s
JOIN resources r ON r.id = s.resource_id
JOIN asset_reviews v ON v.asset_id = s.current_asset_id
  AND v.tenant_id = r.tenant_id
  AND v.workspace_id IS NOT DISTINCT FROM r.workspace_id
  AND v.deleted_at = 0
  AND v.status = 'APPROVED'
WHERE s.deleted_at = 0
  AND s.resource_id = ANY($1::varchar[]::bpchar[])
GROUP BY s.resource_id
`

type ResourceApprovalCountsRow struct {
	ResourceID    string
	ApprovedCount int32
}

func (q *Queries) ResourceApprovalCounts(ctx context.Context, ids []string) ([]ResourceApprovalCountsRow, error) {
	rows, err := q.db.Query(ctx, resourceApprovalCounts, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ResourceApprovalCountsRow{}
	for rows.Next() {
		var i ResourceApprovalCountsRow
		if err := rows.Scan(&i.ResourceID, &i.ApprovedCount); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

